********************************************************* Apple IIGS Scheduler** Copyright (c) 1986-1989, * Apple Computer, Inc.* All Rights Reserved** Original Code by * 	John Worthington 20 May 86** Convted to ASM816*	John Worthington 3 Oct 86** Converted to MAX*	Steven Glass 10 Jun 88** Removed Org *-1*	Steven Glass 7 Oct 88** 17 Oct 88	Steven Glass** References to oEndCall0 and oEndCall4 are now JMLs * since this is orged in bank $FD.** 10 Nov 88	Dave Good & Konstantin Othmer** Changed DecBusy to be faster in the common cases.** 14 Nov 88	Steven Glass** Switched reference to Offset in decBusyFlg to * long addressing because it was made before dbr* was set (changed on 10 Nov 88)** Added line to zero schActive on BootInit and Reset.********************************************************	include '::sys.equs.asm'SchedulerCallTable	PROC Export	import oEndCall0	import oEndCall4	LONGA ON	LONGI ONTheStart	DC.L (TheEnd-TheStart)/4	dc.L SchBootInit-1	; 1	dc.L SchAppInit-1	; 2	dc.L SchApTerm-1	; 3	dc.L Schversion-1	; 4	dc.L SchReset-1	; 5	dc.L SchStatus-1	; 6	dc.L oEndCall0-1	; 7   reserved	dc.L oEndCall0-1	; 8   reserved	dc.L schaddtask-1	; 9	dc.L schflush-1	; 10TheEndSchBootInit	clc 	;Indicate from here	bcc Join	;Let's save a byte of codeSchReset	sec 	;Indicate from hereJoin	lda #$0000	;initialize flags and counters	sta >busyflag	sta >schActive	; init this too! SEG 14 Nov 88	lda #$00FF	sta >offset	bcc @1	jml oEndCall0	;'c'=1 it's reset so exit gracefully.@1*  Set up $E1 jump vectors	lda #incbusy	sta >incbusyflg+1	lda #decbusy	sta >decbusyflg+1	LONGA OFF	sep #$30	;8 bit mode to setup vector	lda #^IncBusy	; bank # of code	sta >incbusyflg+3	;Warning, this assumes both in same	sta >decbusyflg+3	; bank which is not unreasonable.	LONGA ON	rep #$30	;16 bit mode to continueSchAppInit	SchApTerm		jml oEndCall0SchVersion	result	equ 7	lda #$0300	; version 2.0 for new rom	bra SaveResult	;Skip SchStatus setupSchStatus		lda #$FFFFSaveResult		sta result,s	jml oEndCall0* Procedure SchFlush;** Flush the Scheduler's que. Offset is set to $FF if the que is emptyschflush		lda #$00FF	sta >offset	jml oEndCall0* Function SchAddTask (TaskAddr : LONGINT) :boolean;** add a task to Scheduler. If the result is FALSE then there* wasn't room to add the task. Result is TRUE otherwise. ** Note that there is a limit of 4 tasks that can be present in the* Scheduler chain at a given time. If this is a problem, we can * reserve more ram.*schaddtask	taskaddr	equ 8result1	equ 12	LONGI OFF	LONGA OFF	sep #$30	phb 	; set up the data bank	lda #$E0	pha	plb	lda |offset	; number of tasks - 1	inc a	cmp #$04	; only 4 task can be in que	bge @TheError	sta |offset	asl a	asl a	tax	LONGI ON	LONGA ON	rep #$30	lda taskaddr,s	; copy the task from the stack	sta |taskque,x	;   into the que.	inx	inx	lda taskaddr+2,s	sta |taskque,x	lda #$00FF	; return true if the task	bra @TheError1	;   was added.@TheError		; return false otherwise.	LONGI ON	LONGA ON	rep #$30	lda #$0000@TheError1		sta result1,s	plb	jml oEndCall4*******************************************************************   These routines are inserted into the E1 vectors.*     they handle decrementing, incrementing and reading the*     flag. All registers are preserved.**   Note that the routine decbusy will all activate all pending tasks*   in the scheduler que. The tasks will get control of the*   machine in native mode with interrupts disabled. They may*   turn interrupts on. The tasks should return to the scheduler*   with an RTL. The dbr is set to $E0 when the task is activated.*;---------------------------------------------------------------; $E0 variable space for scheduler.;---------------------------------------------------------------SchActive	equ $E01DDE	; new flag for whether we are activetaskque	equ $E01DDF	; 16 byte que -- 4 itemsfirstTask	equ $E01DDFsecondTask	equ $E01DE3	; second item in queoffset	equ $E01DEF;---------------------------------------------------------------;---------------------------------------------------------------; this routine decrements the busy flag and checks to see if it; needs to run any tasks in the scheduler que. If it does, it will; preserve all the registers, call all the que routines, and finally; clear out the que. Each task will get control of the machine in native; mode with interrupts disabled. Each one may turn interrupts on. The; tasks should return to the scheduler with an RTL. The data bank is set; to $E0 when the task is activated.;---------------------------------------------------------------DecBusy	php		;save interrupt status	sei	pha		;preserve the A-Reg	lda  >BusyFlag		;decrement the busy flag	dec  a	sta  >BusyFlag	beq  alreadyZero		;if at zero, check to see if we have tasks	bmi  setZero		;prevent the flag from going below zeroexitBusy	pla	plp	rtlsetZero	lda  #$0000	sta  >BusyFlagalreadyZero	lda  >schActive		;do we have tasks ?	and  #$00FF		;active flag is only one byte.	bne  exitBusy		;..nope, so exit.	lda  >offset-1		;the high byte is offset, so this will	bpl TasksToRun		; if not neg, there are tasks to run.	pla		; restore and get out	plp	rtlTasksToRun;---------------------------------------------------------------	phx		;save the registers	phy	sep #%00100000		;short mode for speed ???	longa off	phb		;save the user's data bank	lda  #$E0		;set data bank to $E0	pha	plb	lda  #$01		; set active flag to prevent recursive	sta  |schActive		; calls to tasks. JW 9-23-86doNextTask	phk		;push our return address	per  @return-1	lda  |firstTask+2		;fancy way of jumping to the task to	pha		;..execute	rep #%00100000		;the task is executed in long mode	longa on	lda  |firstTask	dec  a	pha	rtl@return	rep  #$30		;make sure we are in long mode	longa on	longi on	pea  $E0E0		;set the data bank back to $E0	plb	plb	sei		;make sure interrupts are off	ldx  #0		;move all the tasks up one in the que@loop	lda  |secondTask,x	sta  |firstTask,x	inx	inx	cpx  #$000C+2	blt  @loop	sep #%00100000		;short mode for speed ???	longa off	dec  |offset		;decrement our count	bpl  doNextTask	stz  |schActive	rep #%00100000	longa on	plb	ply	plx	bra  exitBusy;---------------------------------------------------------------;---------------------------------------------------------------; This routine increments the busy flag and saves the A-Reg;---------------------------------------------------------------IncBusy	php	sei	pha	lda  >BusyFlag	inc  a	sta  >BusyFlag	pla	plp	rtl;---------------------------------------------------------------;---------------------------------------------------------------; NOTE: this routine does not preserve the registers since it; returns something in A-Reg... Golly Gee !!! (Does anybody call; this routine ??!?);---------------------------------------------------------------ReadBusy	lda >BusyFlag	rtl;---------------------------------------------------------------	ENDP****************************************************************	END